"""Metrics collection and reporting."""

import time
from typing import Any, Callable


class Counter:
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description
        self._count = 0

    def inc(self, value: int = 1) -> None:
        self._count += value

    def get(self) -> int:
        return self._count

    def reset(self) -> None:
        self._count = 0

    def to_dict(self) -> dict[str, Any]:
        return {"count": self._count}


class Gauge:
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description
        self._value: float = 0.0

    def set(self, value: float) -> None:
        self._value = value

    def get(self) -> float:
        return self._value

    def to_dict(self) -> dict[str, Any]:
        return {"value": self._value}


class Histogram:
    def __init__(self, name: str, buckets: list[float] | None = None, description: str = "") -> None:
        self.name = name
        self.description = description
        self.buckets = buckets or [0.1, 0.5, 1.0, 5.0, 10.0]
        self.reset()

    def reset(self) -> None:
        self._sum = 0.0
        self._count = 0
        self._bucket_counts = [0] * len(self.buckets)

    def observe(self, value: float) -> None:
        self._sum += value
        self._count += 1
        for i, bucket in enumerate(self.buckets):
            if value <= bucket:
                self._bucket_counts[i] += 1

    def sum(self) -> float:
        return self._sum

    def count(self) -> int:
        return self._count

    def avg(self) -> float:
        return self._sum / self._count if self._count > 0 else 0.0

    def percentile(self, p: float) -> float:
        if self._count == 0:
            return 0.0
        # Simplified - in real implementation would use proper percentile calculation
        return self._sum / self._count

    def to_dict(self) -> dict[str, Any]:
        return {
            "count": self._count,
            "sum": self._sum,
            "avg": self.avg(),
            "p50": self.percentile(50),
            "p95": self.percentile(95),
            "p99": self.percentile(99),
        }


class MetricsCollector:
    def __init__(self) -> None:
        self._counters: dict[str, Counter] = {}
        self._gauges: dict[str, Gauge] = {}
        self._histograms: dict[str, Histogram] = {}

    def counter(self, name: str, description: str = "") -> Counter:
        if name not in self._counters:
            self._counters[name] = Counter(name, description)
        return self._counters[name]

    def gauge(self, name: str, description: str = "") -> Gauge:
        if name not in self._gauges:
            self._gauges[name] = Gauge(name, description)
        return self._gauges[name]

    def histogram(self, name: str, buckets: list[float] | None = None, description: str = "") -> Histogram:
        if name not in self._histograms:
            self._histograms[name] = Histogram(name, buckets, description)
        return self._histograms[name]

    def to_dict(self) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for name, counter in self._counters.items():
            result["counters"] = result.get("counters", {})
            result["counters"][name] = counter.to_dict()
        for name, gauge in self._gauges.items():
            result["gauges"] = result.get("gauges", {})
            result["gauges"][name] = gauge.to_dict()
        for name, histogram in self._histograms.items():
            result["histograms"] = result.get("histograms", {})
            result["histograms"][name] = histogram.to_dict()
        return result

    def reset(self) -> None:
        for counter in self._counters.values():
            counter.reset()
        for gauge in self._gauges.values():
            gauge.set(0.0)
        for histogram in self._histograms.values():
            histogram.reset()


_metrics_collector: MetricsCollector | None = None


def get_collector() -> MetricsCollector:
    global _metrics_collector
    if _metrics_collector is None:
        _metrics_collector = MetricsCollector()
    return _metrics_collector


def reset_collector() -> None:
    global _metrics_collector
    if _metrics_collector is not None:
        _metrics_collector.reset()


def counter(name: str, description: str = "") -> Counter:
    return get_collector().counter(name, description)


def gauge(name: str, description: str = "") -> Gauge:
    return get_collector().gauge(name, description)


def histogram(name: str, buckets: list[float] | None = None, description: str = "") -> Histogram:
    return get_collector().histogram(name, buckets, description)
