"""Simple TTL cache for function results."""

import time
from collections import OrderedDict
from functools import wraps
from typing import Any, Callable, TypeVar

F = TypeVar("F", bound=Callable[..., Any])


class TTLCache:
    def __init__(self, maxsize: int = 128, ttl: float = 3600) -> None:
        self.maxsize = maxsize
        self.ttl = ttl
        self._cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()

    def _evict_expired(self) -> None:
        now = time.time()
        expired_keys = [
            key for key, (value, timestamp) in self._cache.items()
            if now - timestamp > self.ttl
        ]
        for key in expired_keys:
            del self._cache[key]

    def get(self, key: str) -> Any:
        self._evict_expired()
        if key in self._cache:
            value, timestamp = self._cache[key]
            if time.time() - timestamp <= self.ttl:
                # Move to end to show recent use
                self._cache.move_to_end(key)
                return value
            else:
                del self._cache[key]
        raise KeyError(key)

    def set(self, key: str, value: Any) -> None:
        self._evict_expired()
        self._cache[key] = (value, time.time())
        self._cache.move_to_end(key)
        if len(self._cache) > self.maxsize:
            # Remove oldest item
            oldest = next(iter(self._cache))
            del self._cache[oldest]

    def clear(self) -> None:
        self._cache.clear()


def ttl_cache(maxsize: int = 128, ttl: float = 3600) -> Callable[[F], F]:
    cache = TTLCache(maxsize=maxsize, ttl=ttl)

    def decorator(func: F) -> F:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            # Create a cache key from args and kwargs
            key = str((args, sorted(kwargs.items())))
            try:
                return cache.get(key)
            except KeyError:
                result = func(*args, **kwargs)
                cache.set(key, result)
                return result

        wrapper.cache = cache  # type: ignore[attr-defined]
        wrapper.cache_clear = cache.clear  # type: ignore[attr-defined]
        return wrapper  # type: ignore[return-value]

    return decorator
