"""Database query ingestion source."""

from typing import Any, Iterator

from .db import execute_query
from .metrics import MetricsCollector, get_collector
from .models import Record


class DatabaseSource:
    def __init__(self, queries: dict[str, str], metrics: MetricsCollector | None = None) -> None:
        self.queries = queries
        self.metrics = metrics or get_collector()

    def iter_records(self, query_name: str, **params: Any) -> Iterator[Record]:
        """Yield records from a named query."""
        if query_name not in self.queries:
            raise ValueError(f"Query '{query_name}' not defined")
        query = self.queries[query_name]
        for row in execute_query(query, tuple(params.values())):
            record = self._row_to_record(row, query_name)
            if record is not None:
                yield record

    def _row_to_record(self, row: tuple[Any, ...], source: str) -> Record | None:
        """Convert database row to Record."""
        if not row:
            return None
        # Convert row tuple to dict
        data = {f"col_{i}": val for i, val in enumerate(row)}
        return Record.from_dict({
            "source": source,
            "data": data,
            "tags": ["db"],
        })

    def read_table(
        self, table: str, columns: list[str] | None = None, where_clause: str = ""
    ) -> Iterator[Record]:
        """Read a table as records."""
        col_list = ", ".join(columns) if columns else "*"
        query = f"SELECT {col_list} FROM {table}"
        if where_clause:
            query += f" WHERE {where_clause}"
        for row in execute_query(query):
            record = self._row_to_record(row, table)
            if record is not None:
                self.metrics.counter("db.records.read").inc()
                yield record

    def ingest_from_tables(
        self,
        tables: list[str],
        columns: list[str] | None = None,
        where_clause: str = "",
        batch_size: int = 1000,
    ) -> Iterator[list[Record]]:
        """Ingest multiple tables in batches."""
        batch: list[Record] = []
        for table in tables:
            for record in self.read_table(table, columns, where_clause):
                batch.append(record)
                if len(batch) >= batch_size:
                    self.metrics.counter("db.batches.read").inc()
                    yield batch
                    batch = []
        if batch:
            self.metrics.counter("db.batches.read").inc()
            yield batch

    def get_table_row_count(self, table: str) -> int:
        """Get approximate row count for a table."""
        result = execute_query(f"SELECT COUNT(*) FROM {table}")
        if result and len(result) > 0 and len(result[0]) > 0:
            return int(result[0][0])
        return 0


