    def flush(self) -> None:
        pass

    def close(self) -> None:
        pass

    def __enter__(self) -> "ConsoleWriter":
        return self

    def __exit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        pass


class MultiWriter:
    def __init__(self, writers: list[RecordWriter]) -> None:
        self.writers = writers

    def write_record(self, record: Record) -> None:
        for writer in self.writers:
            writer.write_record(record)

    def flush(self) -> None:
        for writer in self.writers:
            writer.flush()

    def close(self) -> None:
        for writer in self.writers:
            writer.close()

    def __enter__(self) -> "MultiWriter":
        return self

    def __exit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        self.close()


def write_records(records: list[Record], writer: RecordWriter) -> None:
    for record in records:
        writer.write_record(record)
    writer.flush()


def create_writer(output: str | None = None, format: str = "jsonl", append: bool = True) -> RecordWriter:
    if output:
        if format == "csv":
            return CsvWriter(output, append)
        elif format == "db":
            return DatabaseWriter(output)
        else:
            return JsonlWriter(output, append)
    return ConsoleWriter()
