"""Record validation and schema enforcement."""

from typing import Any, Callable

from .models import Record

Schema = dict[str, type]


class ValidationError(Exception):
    """Raised when record validation fails."""
    pass


class Validator:
    def __init__(self, schema: Schema) -> None:
        self.schema = schema
        self._custom_validators: list[Callable[[Record], Any]] = []

    def add_validator(self, func: Callable[[Record], Any]) -> None:
        self._custom_validators.append(func)

    def validate(self, record: Record) -> bool:
        """Validate a record against the schema."""
        for field, expected_type in self.schema.items():
            if field not in record.data:
                if field.endswith("?"):
                    continue
                raise ValidationError(f"Missing field: {field}")

            value = record.data[field.rstrip("?")]
            if value is not None:
                if not isinstance(value, expected_type):
                    raise ValidationError(
                        f"Field {field}: expected {expected_type}, got {type(value)}"
                    )

        for validator_func in self._custom_validators:
            validator_func(record)

        return True

    def validate_batch(self, records: list[Record]) -> tuple[list[Record], list[tuple[Record, Exception]]]:
        """Validate a batch of records. Returns (valid_records, errors)."""
        valid: list[Record] = []
        errors: list[tuple[Record, Exception]] = []
        for record in records:
            try:
                if self.validate(record):
                    valid.append(record)
            except ValidationError as e:
