"""Record transformation and enrichment."""

import json
from typing import Any, Callable, Iterator

from .models import Record

TransformFunc = Callable[[Record], Record]


def compose(transforms: list[TransformFunc]) -> TransformFunc:
    """Compose multiple transforms into one."""

    def composed(record: Record) -> Record:
        result = record
        for transform in transforms:
            result = transform(result)
        return result

    return composed


def map_field(record: Record, source_field: str, target_field: str) -> Record:
    """Rename or map a field."""
    if source_field in record.data:
        record.data[target_field] = record.data.pop(source_field)
    return record


def drop_field(record: Record, field_name: str) -> Record:
    """Remove a field from the record."""
    record.data.pop(field_name, None)
    return record


def keep_fields(record: Record, fields: list[str]) -> Record:
    """Keep only specified fields."""
    record.data = {k: v for k, v in record.data.items() if k in fields}
    return record


def add_field(record: Record, name: str, value: Any) -> Record:
    """Add a new field with a static value."""
    record.data[name] = value
    return record


def parse_json_field(record: Record, field: str) -> Record:
    """Parse a JSON string field into a dict."""
    if field in record.data and isinstance(record.data[field], str):
        try:
            record.data[field] = json.loads(record.data[field])
        except json.JSONDecodeError:
            pass
    return record


def flatten(record: Record, separator: str = "_") -> Record:
    """Flatten nested dictionaries."""
    new_data: dict[str, Any] = {}
    for key, value in record.data.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                new_data[f"{key}{separator}{subkey}"] = subvalue
        else:
            new_data[key] = value
    record.data = new_data
    return record


def add_timestamp(record: Record, field: str = "processed_at") -> Record:
    """Add a timestamp field to the record."""
    import time

    record.data[field] = time.time()
    return record


class TransformRegistry:
    def __init__(self) -> None:
        self._transforms: dict[str, TransformFunc] = {}

    def register(self, name: str, func: TransformFunc) -> None:
        self._transforms[name] = func

    def get(self, name: str) -> TransformFunc:
        if name not in self._transforms:
            raise KeyError(f"Transform '{name}' not found")
        return self._transforms[name]

    def list(self) -> list[str]:
        return list(self._transforms.keys())


_registry = TransformRegistry()


def register_transform(name: str, func: TransformFunc) -> None:
    _registry.register(name, func)


def get_transform(name: str) -> TransformFunc:
    return _registry.get(name)


def build_pipeline(steps: list[str]) -> TransformFunc:
    """Build a transform pipeline from named transforms."""
    transforms = [get_transform(step) for step in steps]
    return compose(transforms)


