"""Job scheduler for periodic ingestion."""

import time
from typing import Any, Callable

JobFunc = Callable[..., None]


class Job:
    def __init__(
        self, name: str, func: JobFunc, interval: float = 3600
    ) -> None:
        self.name = name
        self.func = func
        self.interval = interval
        self.last_run: float = 0.0
        self.enabled = True
        self.metadata: dict[str, Any] = {}

    def is_due(self) -> bool:
        if not self.enabled:
            return False
        return time.time() - self.last_run >= self.interval

    def execute(self) -> None:
        try:
            self.func()
            self.last_run = time.time()
        except Exception as e:
            self.metadata["last_error"] = str(e)
            raise

    def status(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "enabled": self.enabled,
            "interval": self.interval,
            "last_run": self.last_run,
            "next_run": self.last_run + self.interval if self.enabled else None,
        }


class Scheduler:
    def __init__(self) -> None:
        self._jobs: dict[str, Job] = {}
        self._running = False

    def add_job(self, name: str, func: JobFunc, interval: float = 3600) -> None:
        self._jobs[name] = Job(name, func, interval)

    def remove_job(self, name: str) -> None:
        if name in self._jobs:
            del self._jobs[name]

    def get_job(self, name: str) -> Job:
        return self._jobs[name]

    def list_jobs(self) -> list[str]:
        return list(self._jobs.keys())

    def run_pending(self) -> None:
        for job in self._jobs.values():
            if job.is_due():
                job.execute()

    def run_loop(self) -> None:
        self._running = True
        while self._running:
            self.run_pending()
            time.sleep(1)

    def stop(self) -> None:
        self._running = False


_default_scheduler: Scheduler | None = None


def get_scheduler() -> Scheduler:
    global _default_scheduler
    if _default_scheduler is None:
        _default_scheduler = Scheduler()
    return _default_scheduler


def add_job(name: str, func: JobFunc, interval: float = 3600) -> None:
    get_scheduler().add_job(name, func, interval)
